(select gavInfo.finprodAbbr,gavInfo.finprodMarketId,gavInfo.portFolioName, gavInfo.marketValue,gavInfo.dscCostAmt,gavInfo.shareAmt, round(nvl(gavInfo.marketValue,0)/ppvInfo.tdyAssetValue*100,2) as marketValueRatio,gavInfo.portfolioId,ppvInfo.tdyAssetValue from (select psv.CDATE cdate,psv.PORTFOLIO_ID portfolioId,psv.FINPROD_ID finprodId, psv.MARKET_VALUE marketValue,psv.SHARE_AMT shareAmt,psv.DSC_COST_AMT dscCostAmt, pp.PORTFOLIO_NAME portFolioName,fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr from PTL_SEC_PIERCE_VALUTION psv inner join PTL_PORTFOLIO pp on psv.PORTFOLIO_ID=pp.PORTFOLIO_ID inner join FIN_PRODUCT fp on fp.FINPROD_ID=psv.FINPROD_ID where 1=1
